"""Weekly timesheet rows, one line of text per worker."""

from typing import List, Dict
from hourglass.schedule import worker_minutes
from hourglass.models import Shift
from hourglass.errors import ProjectError
from collections import Counter


def _check(shifts: List[Shift]) -> None:
    if not shifts:
        raise ProjectError("no shifts to total")
    for shift in shifts:
        if not shift.worker.strip():
            raise ProjectError("blank worker name")


def _ranked(minutes: Dict[str, int]) -> List[str]:
    return sorted(
        minutes,
        key=lambda name: (-minutes[name], name)
    )


def _row(name: str, count: int, minutes: int) -> str:
    hours = minutes / 60
    return f"{name}: {count} shifts, {hours:.1f} hours"


def format_timesheet(shifts: List[Shift]) -> List[str]:
    """Name, shift count and hours per worker, busiest first."""
    _check(shifts)
    minutes = worker_minutes(shifts)
    counts = Counter(shift.worker for shift in shifts)
    return [
        _row(name, counts[name], minutes[name])
        for name in _ranked(minutes)
    ]

